-- Ports and generics named like Verilog keywords, extended identifiers
-- and long names
entity names24 is
    generic (\Gen\ : integer := 3;
             \output\ : integer := 4;
             _g : integer := 5);
    port (reg    : in bit;
          \wire\ : out bit;
          \Mixed\ : out bit;
          _p : out bit);
end entity;

architecture test of names24 is
begin
    \wire\ <= reg;
    \Mixed\ <= '1' when \Gen\ = 6 and \output\ = 4 and _g = 5
               else '0';
    _p <= not reg;
end architecture;
